function pointer(selector,click=false){if(!$('#guided').checked||mode!=='demo')return;const target=$(selector);if(!target||target.hidden)return;const panel=target.closest('[role=tabpanel]');if(panel?.hidden)selectPanel(panel.id);const r=target.getBoundingClientRect();if(r.top<85||r.bottom>innerHeight-30){target.scrollIntoView({block:'center',behavior:'instant'});}const b=target.getBoundingClientRect();const c=$('#demoCursor');c.hidden=false;c.style.left=(b.left+Math.min(b.width*.62,160))+'px';c.style.top=(b.top+b.height/2)+'px';c.classList.toggle('clicking',click);if(click){target.classList.add('cursor-hit');setTimeout(()=>{target.classList.remove('cursor-hit');c.classList.remove('clicking');},250);}}
