 $('#recommendation').hidden=!agentState.recommendation||!isRewardsDemo();if(agentState.recommendation){const r=agentState.recommendation;$('#recommendation').className='recommend';$('#recommendation').innerHTML=`<div class="eyebrow">RECOMMENDED RESPONSE</div><h2>${esc(r.title)}</h2><p class="solution">${esc(r.solution)}</p><details class="answer-details"><summary>View suggested wording</summary><div class="answer">${esc(r.answer)}</div></details><div class="actions"><button id="createCase" class="primary" ${!followupAllowed||followup?'disabled':''}>${followup?'✓ Follow-up registered':'Register follow-up'}</button><button id="copyAnswer">Copy answer</button></div><small class="fine">${followup?'Mock request SM-DEMO-084 registered.':followupAllowed?'Customer consent received.':'Follow-up is enabled after customer consent.'}</small>`;}
