$('#play').onclick=()=>{if(phase==='idle')return start();if(phase==='complete'){reset();return start();}paused=!paused;if(paused){audio.pause();stopRing();}else{if(phase==='ringing')ring();if(['verification','request','resolution'].includes(phase))playMedia();}render();};$('#endCall').onclick=()=>{if(['idle','complete'].includes(phase))return;outbound('end_call');if(mode==='live')return;if(['hold','answer-ready'].includes(phase))holdSeconds+=clock-holdStart;audio.pause();stopRing();autoJobs=[];jobs.clear();runActive=false;clearTimeout(workflowTimer);phase='complete';paused=false;$('#demoCursor').hidden=true;render();};$('#reset').onclick=()=>{reset();$('#settings').close();};$('#settingsOpen').onclick=()=>$('#settings').showModal();$('#settingsClose').onclick=()=>$('#settings').close();$('#verifyDob').onclick=()=>verify('dob');$('#verifyId').onclick=()=>verify('id');$('#callAction').onclick=()=>{if(mode==='live'){outbound(phase==='ringing'?'accept_call':phase==='awaiting-hold'?'hold_call':phase==='followup'?'create_followup_case':'resume_call');return;}if(phase==='ringing')accept();else if(phase==='awaiting-hold')hold();else if(['hold','answer-ready','answer-ready-returned'].includes(phase))resume();else if(phase==='followup')registerFollowup();};
$('#guided').onchange=()=>{if(!$('#guided').checked)$('#demoCursor').hidden=true;};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.id.startsWith('crumb-')){const id=b.id.split('-')[1];const m=$('#menu-'+id);m.hidden=!m.hidden;b.setAttribute('aria-expanded',String(!m.hidden));}if(b.dataset.level!==undefined){const i=Number(b.dataset.level);chosen[i]=b.dataset.value;for(let n=i+1;n<4;n++)chosen[n]=null;selected=chosen.map(Boolean);prepareWorkflow();outbound('select_classification',{level:i+1,label:chosen[i],path:[...chosen]});render();$('#menu-'+i).hidden=true;$('#crumb-'+i).setAttribute('aria-expanded','false');}if(b.dataset.system){const c=agentState.cards.find(c=>c.id===b.dataset.system);if(c)openSystemDetails(c);}if(b.id==='createCase')registerFollowup();if(b.id==='copyAnswer'){try{await navigator.clipboard.writeText(agentState.recommendation.answer);announce('Answer copied.');}catch{announce('Select the answer text to copy it.');}}if(b.id==='retryAudio'){audio.load();playMedia();}});$('#close').onclick=()=>$('#evidence').close();
function enterLive(){if(mode==='live')return;cancelManual();clearTimeout(workflowTimer);epoch++;audio.pause();stopRing();autoJobs=[];jobs.clear();$('#demoCursor').hidden=true;mode='live';phase='live';runId=null;runActive=false;backendStatus='Ready';render();}
async function connectAgent({url,input=getRunInput(),headers={}}){enterLive();aborter?.abort();aborter=new AbortController();const token=epoch;backendStatus='Connecting';render();try{const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json',Accept:'text/event-stream',...headers},credentials:'same-origin',body:JSON.stringify(input),signal:aborter.signal});if(!r.ok||!r.body)throw Error('Agent endpoint HTTP '+r.status);if(!r.headers.get('content-type')?.includes('text/event-stream'))throw Error('Expected text/event-stream');backendStatus='Connected';const parser=new SSEDecoder(e=>receiveEvent(e,{epoch:token,callId,runId:input.runId}));const reader=r.body.getReader(),decoder=new TextDecoder();while(true){const {done,value}=await reader.read();if(done)break;if(token!==epoch){await reader.cancel();return;}parser.push(decoder.decode(value,{stream:true}));}parser.push(decoder.decode());parser.finish();if(runActive)throw Error('Stream ended before RUN_FINISHED or RUN_ERROR');backendStatus='Completed';}catch(e){if(e.name!=='AbortError'&&token===epoch){backendStatus='Connection error';announce(e.message);window.dispatchEvent(new CustomEvent('sentimeter:connection-error',{detail:{message:e.message}}));}}finally{render();}}
window.sentimeter={version:'1.0.0',callId,getRunInput,getState:()=>structuredClone(agentState),getEvents:()=>structuredClone(log),getTranscript:()=>transcripts.values(),setMode:v=>{if(v==='live')enterLive();else if(v==='demo')reset();else throw Error('Unknown mode');},receiveEvent:(e,scope)=>{enterLive();return receiveEvent(e,scope);},ingestTranscript:s=>{enterLive();return ingestTranscript(s);},connectAgent,disconnect:()=>{aborter?.abort();backendStatus='Disconnected';runActive=false;render();},setCallState:s=>{enterLive();if(s.callId!==callId)return false;if(s.verified){verified={dob:!!s.verified.dob,id:!!s.verified.id};}if(typeof s.elapsedSeconds==='number')clock=s.elapsedSeconds;if(s.classification){chosen=s.classification.map((x,i)=>typeof x==='string'?x:x?rewardLabels[i]:null);selected=chosen.map(Boolean);prepareWorkflow();intent=true;}if(typeof s.followupAllowed==='boolean')followupAllowed=s.followupAllowed;if(s.followupConfirmed){followup=true;}if(s.eligible){eligible={dob:!!s.eligible.dob,id:!!s.eligible.id};}if(s.phase&&['live','ringing','awaiting-hold','answer-ready','followup','complete'].includes(s.phase))phase=s.phase;render();return true;}};
function frame(now){const dt=Math.min((now-lastFrame)/1000,.1);lastFrame=now;if(!paused&&mode==='demo'&&!mediaBlocked){const mediaPhase=['verification','request','resolution'].includes(phase);if(mediaPhase&&!audio.paused&&audio.readyState>=3){clock=audioOffset+audio.currentTime;processMedia();}else if(!mediaPhase&&!['idle','complete'].includes(phase)){clock+=dt;stageElapsed+=dt;}if(['hold','live-returned'].includes(phase))runMockInvestigation();const due=autoJobs.filter(j=>j.at<=clock&&j.epoch===epoch);autoJobs=autoJobs.filter(j=>j.at>clock&&j.epoch===epoch);for(const j of due)j.fn();render();}requestAnimationFrame(frame);}render();requestAnimationFrame(frame);

function selectPanel(id){const panel=document.getElementById(id);if(!panel)return;const side=panel.closest('aside');side.querySelectorAll('[role=tabpanel]').forEach(p=>p.hidden=p.id!==id);side.querySelectorAll('[role=tab]').forEach(t=>{const active=t.dataset.tabPanel===id;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;});if(id==='transcriptPanel')$('#transcript').scrollTop=$('#transcript').scrollHeight;}
document.querySelectorAll('[role=tab]').forEach(tab=>{tab.addEventListener('click',()=>selectPanel(tab.dataset.tabPanel));tab.addEventListener('keydown',e=>{const tabs=[...tab.parentElement.querySelectorAll('[role=tab]')];let index=tabs.indexOf(tab);if(e.key==='ArrowRight')index=(index+1)%tabs.length;else if(e.key==='ArrowLeft')index=(index-1+tabs.length)%tabs.length;else if(e.key==='Home')index=0;else if(e.key==='End')index=tabs.length-1;else return;e.preventDefault();selectPanel(tabs[index].dataset.tabPanel);tabs[index].focus();});});
